<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { Edit3, Plus, RefreshCw, Search } from 'lucide-vue-next';import { ElMessage } from 'element-plus';import { api } from '../api';import OperationsMap from '../components/OperationsMap.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import type { OperationRegionItem, PageData } from '../types';
const session=useSessionStore(),loading=ref(false),saving=ref(false),error=ref(''),rows=ref<OperationRegionItem[]>([]),total=ref(0),page=ref(1),q=ref(''),enterpriseId=ref(''),status=ref(''),selectedId=ref(''),dialog=ref(false),editingId=ref('');const options=reactive<any>({enterprises:[],organizations:[],vehicles:[],approvalResults:[]});const form=reactive({businessNo:'',name:'',regionType:'OPERATION',enterpriseId:'',organizationId:'',approvalResultId:'',validFrom:'',validTo:'',approvalStatus:'APPROVED',speedLimit:20,allowedHours:'06:00-22:00',ruleDescription:'',vehicleIds:[] as string[],polygonText:''});const canWrite=computed(()=>session.user?.permissions.includes('operation:region:write'));const selected=computed(()=>rows.value.find(item=>item.id===selectedId.value)??rows.value[0]);const vehicleOptions=computed(()=>options.vehicles.filter((v:any)=>!form.enterpriseId||v.enterpriseId===form.enterpriseId));let timer:number|undefined;
async function loadOptions(){Object.assign(options,await api<any>('/operations/options'))}async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'50'});if(q.value)p.set('q',q.value);if(enterpriseId.value)p.set('enterpriseId',enterpriseId.value);if(status.value)p.set('status',status.value);const data=await api<PageData<OperationRegionItem>>(`/operations/regions?${p}`);rows.value=data.items;total.value=data.total;if(!rows.value.some(r=>r.id===selectedId.value))selectedId.value=rows.value[0]?.id??''}catch(reason){error.value=reason instanceof Error?reason.message:'运行区域加载失败'}finally{loading.value=false}}watch([q,enterpriseId,status],()=>{clearTimeout(timer);timer=window.setTimeout(load,180)});watch(page,load);onMounted(()=>Promise.all([load(),loadOptions()]));const date=(v?:string|null)=>v?.slice(0,10)??'';const approvalText=(v:string)=>({APPROVED:'已批准',PENDING:'待审批',REJECTED:'已驳回'}as any)[v]??v;
function openForm(row?:OperationRegionItem){editingId.value=row?.id??'';Object.assign(form,row?{businessNo:row.businessNo,name:row.name,regionType:row.regionType,enterpriseId:row.enterpriseId??'',organizationId:row.organizationId,approvalResultId:row.approvalResult?.id??'',validFrom:date(row.validFrom),validTo:date(row.validTo),approvalStatus:row.approvalStatus,speedLimit:row.speedLimit,allowedHours:row.allowedHours??'',ruleDescription:row.ruleDescription??'',vehicleIds:row.vehicles.map(v=>v.vehicle.id),polygonText:row.polygon.map(p=>`${p.longitude},${p.latitude}`).join('\n')}:{businessNo:`REGION-${new Date().getFullYear()}-`,name:'',regionType:'OPERATION',enterpriseId:'',organizationId:options.organizations[0]?.id??'',approvalResultId:'',validFrom:date(new Date().toISOString()),validTo:'',approvalStatus:'APPROVED',speedLimit:20,allowedHours:'06:00-22:00',ruleDescription:'',vehicleIds:[],polygonText:'120.0024,30.2766\n120.0186,30.2790\n120.0198,30.2884\n120.0116,30.2928\n120.0062,30.2922'});dialog.value=true}
function polygon(){const result=form.polygonText.split(/\r?\n/).map(line=>line.split(',').map(Number)).filter(pair=>pair.length===2&&pair.every(Number.isFinite)).map(([longitude,latitude])=>({longitude,latitude}));if(result.length<3)throw new Error('请至少填写 3 行有效经纬度，格式为 经度,纬度');return result}
async function save(){if(!form.businessNo||!form.name||!form.organizationId||!form.validFrom)return ElMessage.warning('请填写区域编号、名称、管理机构和生效日期');saving.value=true;try{const payload={...form,enterpriseId:form.enterpriseId||undefined,approvalResultId:form.approvalResultId||undefined,validTo:form.validTo||undefined,polygon:polygon()};delete (payload as any).polygonText;await api(editingId.value?`/operations/regions/${editingId.value}`:'/operations/regions',{method:editingId.value?'PATCH':'POST',body:JSON.stringify(payload)});ElMessage.success(editingId.value?'运行区域已保存':'运行区域已创建');dialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'保存失败')}finally{saving.value=false}}
async function toggle(row:OperationRegionItem){try{await api(`/operations/regions/${row.id}/status`,{method:'PATCH',body:JSON.stringify({status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE'})});ElMessage.success(row.status==='ACTIVE'?'区域已停用':'区域已启用');await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'状态更新失败')}}
</script>
<template><PageHeader title="运行区域" description="管理已批准的运营范围、关联企业车辆、生效时间与区域规则。" :count="total"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button v-if="canWrite" type="primary" :icon="Plus" @click="openForm()">新增区域</el-button></PageHeader><div class="table-toolbar operation-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索区域编号、名称或企业"/><el-select v-model="enterpriseId" clearable filterable placeholder="全部企业"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="status" clearable placeholder="全部启用状态"><el-option label="已启用" value="ACTIVE"/><el-option label="已停用" value="INACTIVE"/></el-select></div><div v-if="error" class="error-state"><strong>运行区域暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="region-workspace"><OperationsMap mode="regions" :regions="rows" height="620px" @region-select="selectedId=$event"/><aside class="region-rail"><button v-for="row in rows" :key="row.id" :class="{active:selected?.id===row.id}" @click="selectedId=row.id"><span><strong>{{row.name}}</strong><small>{{row.businessNo}} · {{row.organization.name}}</small></span><el-tag size="small" :type="row.approvalStatus==='APPROVED'?'success':row.approvalStatus==='PENDING'?'warning':'danger'">{{approvalText(row.approvalStatus)}}</el-tag></button></aside></div><section v-if="selected" class="region-detail"><header><div><span>{{selected.businessNo}}</span><h2>{{selected.name}}</h2></div><div><el-button v-if="canWrite" :icon="Edit3" @click="openForm(selected)">编辑</el-button><el-button v-if="canWrite" :type="selected.status==='ACTIVE'?'danger':'primary'" plain @click="toggle(selected)">{{selected.status==='ACTIVE'?'停用区域':'启用区域'}}</el-button></div></header><dl class="selected-data"><div><dt>关联企业</dt><dd>{{selected.enterprise?.name||'跨企业公共区域'}}</dd></div><div><dt>关联车辆</dt><dd>{{selected.vehicles.length}} 辆</dd></div><div><dt>生效时间</dt><dd>{{date(selected.validFrom)}} 至 {{date(selected.validTo)||'长期'}}</dd></div><div><dt>审批依据</dt><dd>{{selected.approvalResult?.documentNo||approvalText(selected.approvalStatus)}}</dd></div><div><dt>限速规则</dt><dd>{{selected.speedLimit}} km/h · {{selected.allowedHours||'全天'}}</dd></div><div><dt>运行记录</dt><dd>{{selected._count.records}} 条</dd></div><div class="detail-span-2"><dt>区域规则</dt><dd>{{selected.ruleDescription||'—'}}</dd></div></dl></section>
  <el-dialog v-model="dialog" :title="editingId?'编辑运行区域':'新增运行区域'" width="760px" destroy-on-close><p class="dialog-note">区域边界存入后端并作为地图 Polygon 展示；待审批区域不能直接启用。</p><div class="form-grid"><el-form-item label="区域编号" required><el-input v-model="form.businessNo"/></el-form-item><el-form-item label="区域名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="区域类型"><el-select v-model="form.regionType"><el-option label="运营区域" value="OPERATION"/><el-option label="道路测试区" value="ROAD_TEST"/><el-option label="临时区域" value="TEMPORARY"/></el-select></el-form-item><el-form-item label="管理机构" required><el-select v-model="form.organizationId"><el-option v-for="item in options.organizations" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="关联企业"><el-select v-model="form.enterpriseId" clearable filterable @change="form.vehicleIds=[]"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="关联车辆"><el-select v-model="form.vehicleIds" multiple collapse-tags filterable><el-option v-for="item in vehicleOptions" :key="item.id" :label="`${item.name} · ${item.businessNo}`" :value="item.id"/></el-select></el-form-item><el-form-item label="审批状态"><el-select v-model="form.approvalStatus"><el-option label="已批准" value="APPROVED"/><el-option label="待审批" value="PENDING"/><el-option label="已驳回" value="REJECTED"/></el-select></el-form-item><el-form-item label="审批结果"><el-select v-model="form.approvalResultId" clearable><el-option v-for="item in options.approvalResults" :key="item.id" :label="item.documentNo" :value="item.id"/></el-select></el-form-item><el-form-item label="生效日期" required><el-date-picker v-model="form.validFrom" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="form.validTo" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="限速（km/h）"><el-input-number v-model="form.speedLimit" :min="1" :max="80"/></el-form-item><el-form-item label="允许时段"><el-input v-model="form.allowedHours"/></el-form-item><el-form-item label="边界坐标" class="form-span-2" required><el-input v-model="form.polygonText" type="textarea" :rows="5" placeholder="每行一个坐标：120.0000,30.2700"/></el-form-item><el-form-item label="区域规则" class="form-span-2"><el-input v-model="form.ruleDescription" type="textarea" :rows="3"/></el-form-item></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存区域</el-button></template></el-dialog>
</template>
